-- Actualiza plantilla Receta Médica (colores en impresión)
DECLARE @IdEmpresa INT = 60;
UPDATE dbo.PlantillasDocumentosClinicos
SET ContenidoHTML = N'<!DOCTYPE html> <html lang="es"> <head> <meta charset="UTF-8"> <title>Receta Médica</title> <style> @page { size: A4 portrait; margin: 12mm; } * { box-sizing: border-box; margin: 0; padding: 0; -webkit-print-color-adjust: exact; print-color-adjust: exact; } body { font-family: ''Segoe UI'', Arial, Helvetica, sans-serif; color: #1e3a5f; background: #fff; -webkit-print-color-adjust: exact; print-color-adjust: exact; } .pagina { width: 100%; max-width: 210mm; min-height: 277mm; margin: 0 auto; padding: 18px 22px 0; position: relative; overflow: hidden; } .deco-top { position: absolute; top: -30px; right: -40px; width: 220px; height: 220px; background: linear-gradient(135deg, #dbeafe 0%, #93c5fd 55%, #3b82f6 100%); border-radius: 45% 55% 60% 40%; opacity: 0.35; z-index: 0; } .deco-bottom { position: absolute; bottom: 70px; left: -50px; width: 180px; height: 180px; background: linear-gradient(135deg, #bfdbfe 0%, #60a5fa 100%); border-radius: 50% 40% 55% 45%; opacity: 0.25; z-index: 0; } .contenido { position: relative; z-index: 1; } .header { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; margin-bottom: 18px; } .brand { display: flex; align-items: center; gap: 12px; max-width: 62%; } .logo-box { width: 58px; height: 58px; border-radius: 14px; background: linear-gradient(135deg, #2563eb, #1d4ed8); display: flex; align-items: center; justify-content: center; color: #fff; font-size: 28px; flex-shrink: 0; } .brand h1 { font-size: 20px; font-weight: 800; letter-spacing: 0.3px; color: #1e40af; line-height: 1.15; } .brand p { font-size: 11px; color: #64748b; margin-top: 4px; } .meta-doc { text-align: right; min-width: 170px; } .numero-badge { display: inline-block; background: #1e3a8a; color: #fff; font-weight: 700; font-size: 12px; padding: 6px 14px; border-radius: 8px; margin-bottom: 8px; } .fecha-emision { font-size: 11px; color: #475569; font-weight: 600; } .titulo-wrap { text-align: center; margin: 8px 0 22px; } .titulo-wrap h2 { font-size: 30px; font-weight: 900; color: #1e3a8a; letter-spacing: 1px; } .subtitulo { margin-top: 8px; font-size: 12px; font-weight: 700; color: #3b82f6; letter-spacing: 0.8px; display: flex; align-items: center; justify-content: center; gap: 10px; } .subtitulo::before, .subtitulo::after { content: ''''; height: 2px; width: 70px; background: #93c5fd; display: inline-block; } .campo { margin-bottom: 14px; } .campo label { display: block; font-size: 11px; font-weight: 800; color: #64748b; letter-spacing: 0.6px; margin-bottom: 4px; } .campo .valor { font-size: 15px; font-weight: 700; color: #0f172a; border-bottom: 2px solid #cbd5e1; padding-bottom: 4px; min-height: 24px; } .campo-inline { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 8px; } .seccion-label { font-size: 13px; font-weight: 700; color: #1e40af; margin: 20px 0 8px; text-transform: uppercase; letter-spacing: 0.5px; } .caja-contenido { background: #eff6ff; border: 1px solid #bfdbfe; border-radius: 12px; padding: 16px; font-size: 14px; color: #0f172a; line-height: 1.6; min-height: 120px; white-space: pre-wrap; } .caja-indicaciones { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 12px; padding: 16px; font-size: 14px; color: #334155; line-height: 1.6; min-height: 90px; white-space: pre-wrap; } .firmas { display: flex; justify-content: flex-end; align-items: flex-end; gap: 28px; margin: 36px 0 24px; padding-right: 10px; } .bloque-firma { text-align: center; width: 220px; } .firma-img { min-height: 58px; display: flex; align-items: flex-end; justify-content: center; margin-bottom: 6px; } .firma-img img { max-height: 58px; max-width: 180px; object-fit: contain; } .linea-firma { border-top: 2px solid #1e3a8a; padding-top: 6px; } .nombre-doctor { font-size: 14px; font-weight: 800; color: #1e3a8a; } .titulo-doctor { font-size: 11px; color: #64748b; margin-top: 2px; } .sello-area { width: 96px; height: 96px; border: 2px dashed #93c5fd; border-radius: 50%; display: flex; align-items: center; justify-content: center; overflow: hidden; background: #f8fafc; } .sello-area img { width: 100%; height: 100%; object-fit: cover; border-radius: 50%; } .footer-contacto { position: relative; left: -22px; width: calc(100% + 44px); background: #1e3a8a; color: #fff; padding: 12px 20px; display: flex; flex-wrap: wrap; justify-content: space-around; gap: 10px 18px; font-size: 10px; } .footer-item { display: flex; align-items: center; gap: 6px; } @media print { html, body { margin: 0; background: #fff !important; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; } * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; } .pagina { max-width: none; min-height: auto; padding-bottom: 0; } .deco-top { background: #93c5fd !important; opacity: 0.35 !important; } .deco-bottom { background: #60a5fa !important; opacity: 0.25 !important; } .logo-box { background: #2563eb !important; color: #fff !important; } .brand h1 { color: #1e40af !important; } .numero-badge { background: #1e3a8a !important; color: #fff !important; } .titulo-wrap h2 { color: #1e3a8a !important; } .subtitulo { color: #3b82f6 !important; } .subtitulo::before, .subtitulo::after { background: #93c5fd !important; } .seccion-label { color: #1e40af !important; } .caja-contenido { background: #eff6ff !important; border-color: #bfdbfe !important; } .caja-indicaciones { background: #f8fafc !important; border-color: #e2e8f0 !important; } .linea-firma { border-color: #1e3a8a !important; } .nombre-doctor { color: #1e3a8a !important; } .sello-area { border-color: #93c5fd !important; background: #f8fafc !important; } .footer-contacto { background: #1e3a8a !important; color: #fff !important; } } </style> </head> <body> <div class="pagina"> <div class="deco-top"></div> <div class="deco-bottom"></div> <div class="contenido"> <div class="header"> <div class="brand"> <div class="logo-box">🦷</div> <div> <h1>CLÍNICA DENTAL SENA</h1> <p>Cuidamos tu sonrisa, cuidamos de ti</p> </div> </div> <div class="meta-doc"> <div class="numero-badge">N° {{NUMERO_DOCUMENTO}}</div> <div class="fecha-emision">FECHA DE EMISIÓN: {{FECHA}}</div> </div> </div> <div class="titulo-wrap"> <h2>RECETA MÉDICA</h2> <div class="subtitulo">INDICACIONES FARMACOLÓGICAS Y TRATAMIENTO</div> </div> <div class="campo-inline"> <div class="campo"> <label>PACIENTE</label> <div class="valor">{{CLIENTE}}</div> </div> <div class="campo"> <label>CÉDULA</label> <div class="valor">{{CEDULA}}</div> </div> </div> <div class="campo"> <label>FECHA</label> <div class="valor">{{FECHA}}</div> </div> <div class="seccion-label">Medicamentos</div> <div class="caja-contenido">{{MEDICAMENTOS}}</div> <div class="seccion-label">Indicaciones</div> <div class="caja-indicaciones">{{INDICACIONES}}</div> <div class="firmas"> <div class="bloque-firma"> <div class="firma-img">{{FIRMA}}</div> <div class="linea-firma"> <div class="nombre-doctor">{{DOCTOR}}</div> <div class="titulo-doctor">ODONTÓLOGA</div> </div> </div> <div class="sello-area">{{SELLO}}</div> </div> <div class="footer-contacto"> <div class="footer-item">📍 Av. Principal #123, Santo Domingo, RD</div> <div class="footer-item">📞 (809) 123-4567</div> <div class="footer-item">✉ info@clinicadentalsena.com</div> <div class="footer-item">🌐 www.clinicadentalsena.com</div> </div> </div> </div> </body> </html>', Activa = 1
WHERE IdEmpresa = @IdEmpresa AND TipoDocumento = N'Receta Médica' AND EsPredeterminada = 1;
SELECT TipoDocumento, LEN(ContenidoHTML) AS HtmlLength FROM dbo.PlantillasDocumentosClinicos WHERE IdEmpresa = @IdEmpresa AND TipoDocumento IN (N'Receta Médica', N'Certificado Médico');